insert into public.products (id, slug, status, product_type, title, subtitle, short_description, description, category_id, secondary_category_ids, goals, tags, formats, software, technologies, audience, use_cases, features, included_items, requirements, specs, faq, price_amount, currency, compare_at_amount, license_tier, delivery, version, last_updated, file_size_label, creator_id, is_featured, sort_order, published_at) values ('a1000000-0000-4000-8000-000000000001', 'saas-unit-economics-financial-model', 'published', 'spreadsheet', '{"ru":"Финансовая модель SaaS и юнит-экономика на 5 лет","en":"SaaS Unit Economics & 5-Year Financial Model"}'::jsonb, '{"ru":"Когорты, LTV/CAC, отток, P&L и денежный поток в одной модели","en":"Cohorts, LTV/CAC, churn, P&L and cash flow in one model"}'::jsonb, '{"ru":"Финансовая модель для B2B и B2C SaaS: когортный анализ, LTV/CAC, отток, P&L, Cash Flow и три сценария роста.","en":"A financial model for B2B and B2C SaaS: cohort analysis, LTV/CAC, churn, P&L, cash flow and three growth scenarios."}'::jsonb, '{"ru":"Модель для фаундеров и финансовых руководителей SaaS-компаний. Рассчитывает ключевые метрики — MRR, ARR, Net Revenue Retention, срок окупаемости CAC — и строит прогноз денежных потоков на 60 месяцев. Сценарии роста переключаются в одном месте, а дашборд с графиками можно сразу использовать в материалах для инвесторов.","en":"A model for founders and finance leads at SaaS companies. It calculates key metrics — MRR, ARR, net revenue retention, CAC payback — and builds a 60-month cash flow forecast. Growth scenarios switch in one place, and the chart dashboard can go straight into investor materials."}'::jsonb, 'financial-models', array['unit-economics', 'finance']::text[], array['analyze-unit-economics', 'prepare-investors', 'build-saas', 'launch-startup']::text[], array['SaaS', 'LTV/CAC', 'MRR', 'P&L', 'Cash Flow', 'Cohorts']::text[], array['excel', 'google-sheets', 'pdf']::text[], array['Microsoft Excel', 'Google Sheets']::text[], '{}'::text[], '{"ru":["Фаундеры SaaS-стартапов","Финансовые директора и аналитики","Команды, готовящиеся к раунду"],"en":["SaaS founders","Finance leads and analysts","Teams preparing to raise"]}'::jsonb, '{"ru":["Планирование бюджета на год вперёд","Подготовка финансовой части питч-дека","Оценка влияния цены и оттока на выручку"],"en":["Planning next year’s budget","Preparing the financial section of a pitch deck","Testing how pricing and churn affect revenue"]}'::jsonb, '{"ru":["Расчёт CAC, LTV, оттока и когортного удержания","Три сценария роста: консервативный, базовый, агрессивный","Прогноз P&L и денежного потока на 60 месяцев","Дашборд ключевых метрик с графиками для инвесторов","Версия для Google Sheets"],"en":["CAC, LTV, churn and cohort retention calculations","Three growth scenarios: conservative, base and aggressive","60-month P&L and cash flow forecast","Key-metrics dashboard with investor-ready charts","Google Sheets version"]}'::jsonb, '{"ru":["Финансовая модель SaaS (.xlsx)","Ссылка на копию в Google Sheets (PDF)","Шаблон дашборда KPI для инвесторов (.xlsx)","Пошаговое руководство по заполнению (PDF, 28 страниц)"],"en":["SaaS financial model (.xlsx)","Google Sheets copy link (PDF)","Investor KPI dashboard template (.xlsx)","Step-by-step setup guide (PDF, 28 pages)"]}'::jsonb, '{"ru":["Microsoft Excel (настольная версия) или Google Sheets","Базовое понимание SaaS-метрик"],"en":["Microsoft Excel (desktop) or Google Sheets","A basic understanding of SaaS metrics"]}'::jsonb, '[{"label":{"ru":"Вкладки","en":"Tabs"},"value":{"ru":"14","en":"14"}},{"label":{"ru":"Горизонт прогноза","en":"Forecast horizon"},"value":{"ru":"60 месяцев","en":"60 months"}},{"label":{"ru":"Сценарии","en":"Scenarios"},"value":{"ru":"3","en":"3"}},{"label":{"ru":"Руководство","en":"Guide"},"value":{"ru":"PDF, 28 страниц","en":"PDF, 28 pages"}}]'::jsonb, '[{"question":{"ru":"Работает ли модель в Google Таблицах?","en":"Does the model work in Google Sheets?"},"answer":{"ru":"Да. В комплект входят файл .xlsx и ссылка для копирования версии Google Sheets в ваш Google Drive.","en":"Yes. You get the .xlsx file plus a link to copy the Google Sheets version into your Google Drive."}}]'::jsonb, 3490, 'RUB', null, 'commercial', 'download', '4.2', '2025-01-01', '8.4 MB', 'c0000000-0000-4000-8000-000000000001', true, 1, '2025-01-01T00:00:00.000Z') on conflict (id) do nothing;
insert into public.products (id, slug, status, product_type, title, subtitle, short_description, description, category_id, secondary_category_ids, goals, tags, formats, software, technologies, audience, use_cases, features, included_items, requirements, specs, faq, price_amount, currency, compare_at_amount, license_tier, delivery, version, last_updated, file_size_label, creator_id, is_featured, sort_order, published_at) values ('a1000000-0000-4000-8000-000000000002', 'startup-os-notion-workspace', 'published', 'notion-template', '{"ru":"Startup OS — рабочее пространство Notion","en":"Startup OS — Notion Workspace"}'::jsonb, '{"ru":"CRM, база знаний, OKR, спринты и онбординг в одной системе","en":"CRM, wiki, OKRs, sprints and onboarding in one system"}'::jsonb, '{"ru":"Операционная система компании в Notion: CRM, база знаний, OKR, спринты, финансы и онбординг команды.","en":"A company operating system in Notion: CRM, wiki, OKRs, sprints, finance and team onboarding."}'::jsonb, '{"ru":"Единое рабочее пространство вместо разрозненных инструментов. 24 связанные базы данных: задачи по Scrum и Kanban, карточки клиентов и воронка B2B-сделок, квартальные OKR, база знаний с регламентами и дашборд руководителя. Шаблон дублируется в ваш аккаунт Notion и полностью редактируется.","en":"One workspace instead of scattered tools. 24 linked databases: Scrum and Kanban tasks, client records and a B2B deal pipeline, quarterly OKRs, a wiki with SOPs and an executive dashboard. The template is duplicated into your own Notion account and is fully editable."}'::jsonb, 'startup-os', array['startup-systems', 'project-management']::text[], array['launch-startup', 'organize-operations', 'manage-team', 'build-saas']::text[], array['Notion', 'Startup OS', 'CRM', 'OKR', 'Wiki', 'Sprints']::text[], array['notion', 'pdf']::text[], array['Notion']::text[], '{}'::text[], '{"ru":["Фаундеры и операционные руководители","Команды от 2 до 50 человек","Компании, переходящие в Notion"],"en":["Founders and operations leads","Teams of 2 to 50 people","Companies moving to Notion"]}'::jsonb, '{"ru":["Запуск операционных процессов новой компании","Сведение задач, целей и клиентов в одно место","Онбординг новых сотрудников"],"en":["Setting up operations for a new company","Bringing tasks, goals and clients into one place","Onboarding new hires"]}'::jsonb, '{"ru":["Дашборд основателя: выручка, спринты и ключевые метрики","B2B CRM со статусами сделок и контактами","OKR с прогрессом по ключевым результатам","База регламентов, SOP и онбординга","Дублирование в личное или командное пространство Notion"],"en":["Founder dashboard: revenue, sprints and key metrics","B2B CRM with deal stages and contacts","OKRs with key-result progress tracking","Hub for SOPs, procedures and onboarding","Duplicates into a personal or team Notion workspace"]}'::jsonb, '{"ru":["Ссылка на дублирование шаблона Notion","Видео по настройке под ваш бизнес (40 минут)","Гайд по внедрению регламентов в команде (PDF)","Набор иконок и обложек для страниц"],"en":["Notion template duplicate link","Customization walkthrough video (40 minutes)","Team SOP rollout guide (PDF)","Icon and page-cover pack"]}'::jsonb, '{"ru":["Аккаунт Notion","Для командной работы — командное пространство Notion"],"en":["A Notion account","A Notion team workspace for collaborative use"]}'::jsonb, '[{"label":{"ru":"Базы данных","en":"Databases"},"value":{"ru":"24 связанные","en":"24 linked"}},{"label":{"ru":"Страницы и шаблоны","en":"Pages & templates"},"value":{"ru":"45+","en":"45+"}},{"label":{"ru":"Видео","en":"Video"},"value":{"ru":"40 минут","en":"40 minutes"}}]'::jsonb, '[{"question":{"ru":"Как я получу шаблон Notion?","en":"How do I receive the Notion template?"},"answer":{"ru":"После подтверждения оплаты в вашей библиотеке появится ссылка на дублирование. Откройте её, нажмите «Duplicate» и выберите своё рабочее пространство Notion.","en":"Once your payment is confirmed, a duplicate link appears in your library. Open it, click “Duplicate” and choose your Notion workspace."}}]'::jsonb, 2990, 'RUB', null, 'commercial', 'download-and-link', '5.0', '2025-02-01', null, 'c0000000-0000-4000-8000-000000000001', true, 2, '2025-02-01T00:00:00.000Z') on conflict (id) do nothing;
